const { p, h1, h2, h3, bullets, numbered, table, note, code, fig, spacer } = require("./lib");
const d = require("./data");
const ex = d.ev.api_examples;
const js = (o) => JSON.stringify(o, null, 2).split("\n");

exports.q4 = () => [
  h1("Question 4: Implementation Documentation"),
  h2("4.1 Technology stack, structure, modules and interface"),
  table(["Layer", "Technology (version)", "Role"], [
    ["Language / runtime", "Python 3.11", "Backend, AI, simulator, tests"],
    ["Web framework", `FastAPI ${d.ev.versions.fastapi}, Uvicorn ${d.ev.versions.uvicorn}`, "REST API, WebSocket, auto-generated OpenAPI"],
    ["Validation", `Pydantic ${d.ev.versions.pydantic}`, "Rejects malformed input with HTTP 422"],
    ["Database", `MongoDB (Atlas in production); PyMongo ${d.ev.versions.pymongo}; mongomock ${d.ev.versions.mongomock} for tests`, "Documents with GeoJSON and 2dsphere indexes"],
    ["AI / ML", `PyTorch ${d.ev.versions.torch}, OpenCV ${d.ev.versions["opencv-python-headless"]}, NumPy ${d.ev.versions.numpy}`, "CNN classification, hotspot segmentation"],
    ["Front end", "HTML, JavaScript, Leaflet 1.9.4", "Command dashboard and map"],
    ["Security", "HS256 JWT, PBKDF2-SHA256 (Python standard library)", "Authentication and role-based access"],
    ["Packaging", "Docker, Docker Compose (files written, image not built)", "Deployment"],
    ["Testing", `pytest ${d.ev.versions.pytest}, pytest-cov, httpx, websockets, Playwright ${d.ev.versions.playwright}`, "Unit, integration, system tests, screenshots"],
  ], [20, 46, 34]),
  h3("Project structure"),
  code([
    "firesight/",
    "├── app/",
    "│   ├── main.py          FastAPI app factory, REST + WebSocket, dispatch, ingest, mission loop",
    "│   ├── models.py        Pydantic request models (validation rules)",
    "│   ├── security.py      JWT and password hashing",
    "│   ├── db.py            MongoDB connection, seed data, indexes",
    "│   ├── geo.py           haversine, georeferencing (pixel <-> latitude/longitude)",
    "│   ├── spread.py        weather lookup and fire-spread polygon",
    "│   ├── report.py        post-incident report builder",
    "│   ├── ai/              synth.py (data), model.py (CNN), engine.py (inference), train.py",
    "│   ├── hal/             base.py (DroneAdapter), simulator.py (SimulatedDrone, FireScenario)",
    "│   └── static/          index.html, app.js, vendor/leaflet",
    "├── tests/               test_unit.py, test_integration.py, test_system.py",
    "├── scripts/             ui_capture.py, collect_evidence.py",
    "├── artifacts/           junit.xml, coverage.json, *_metrics.json, evidence.json",
    "├── docs/                uml/ (sources + images), screens/",
    "├── Dockerfile   docker-compose.yml   requirements.txt",
  ]),
  spacer(60),
  table(["Module", "Responsibility"], [
    ["`app.main`", "Creates the app; authentication dependency; REST endpoints; WebSocket endpoint and role-filtered `Hub`; dispatch; telemetry and frame ingest; simulation mission loop."],
    ["`app.models`", "Defines and validates every request body (ranges, lengths, patterns)."],
    ["`app.security`", "Issues and verifies signed tokens; hashes and checks passwords."],
    ["`app.db`", "Selects Atlas (`MONGO_URI`) or in-memory store; seeds 3 drones, 4 users, 3 firefighters; creates indexes."],
    ["`app.ai.engine`", "Loads trained weights; decodes frames; classifies; segments and georeferences hotspots."],
    ["`app.ai.synth` / `train`", "Generates synthetic thermal frames; trains the CNN and writes `ai_metrics.json`."],
    ["`app.hal`", "`DroneAdapter` interface, `SimulatedDrone`, `FireScenario` (ground-truth fire), unimplemented `DJIAdapter`."],
    ["`app.spread`", "Reads wind (OpenWeatherMap or simulated) and builds the spread polygon."],
    ["`app.report`", "Builds and stores the incident report."],
    ["`app.static`", "Dashboard: sign-in, map, telemetry, AI panel, spread panel, chat, report."],
  ], [22, 78]),
  h3("Selected interface screenshots"),
  p("The map background is blank in these captures because the build environment cannot reach the OpenStreetMap tile server. On a normal connection the tiles load under the same markers and overlays."),
  ...fig("docs/screens/01_login.png", "Sign-in screen. Access depends on the role held by the account.", 600, 375),
  ...fig("docs/screens/02_dashboard_idle.png", "Operator view with no incident: map, incident list with the \"Simulate CAD alert\" control, empty telemetry and AI panels.", 600, 375),
  ...fig("docs/screens/03_drone_en_route.png", "Incident INC-0001 dispatched: DR-01 flying to the scene, telemetry updating.", 600, 375),
  ...fig("docs/screens/04_critical_detection.png", "On scene: thermal frame with class, confidence, inference time, hotspot overlay, spread polygon and the critical-severity banner.", 600, 375),
  ...fig("docs/screens/05_commander_message.png", "Commander view: a message sent on the command channel.", 600, 375),
  ...fig("docs/screens/06_report.png", "Closed incident and generated report (side panel scrolled to the bottom).", 600, 375),
  ...fig("docs/screens/07_crew_view.png", "Field-crew view: telemetry and AI panels stay empty because crew do not receive those events (privacy control).", 600, 375),

  h2("4.2 Database"),
  ...fig("docs/uml/d8_erd.png", "Entity-relationship diagram of the MongoDB collections (relationships are by id; MongoDB does not enforce foreign keys).", 620, 620),
  h3("Data dictionary"),
  table(["Collection", "Field", "Type", "Rules / notes"], [
    ["`users`", "`_id`", "string", "Username, unique."],
    ["", "`role`", "string", "commander, operator, crew or admin."],
    ["", "`passwordHash`", "string", "Salted PBKDF2-SHA256 (120 000 iterations). Never returned by the API."],
    ["`incidents`", "`_id`", "string", "INC-nnnn from an atomic counter."],
    ["", "`callId`", "string", "Unique CAD call id (duplicates rejected with 409)."],
    ["", "`priority`", "int", "1 to 3."],
    ["", "`status` / `dispatchStatus`", "string", "open, closed / pending, queued, en_route, on_scene."],
    ["", "`location`", "GeoJSON Point", "2dsphere index."],
    ["", "`droneId`, `distanceM`, `dispatchSeconds`", "string, number", "Set on dispatch."],
    ["", "`maxSeverity`, `detections`, `hotspots`", "int, int, array", "Updated by each analysed frame."],
    ["", "`reportedAt`, `closedAt`", "float", "Epoch seconds."],
    ["`drones`", "`_id`, `base`, `status`", "string", "DR-nn; idle, en_route, on_scene."],
    ["", "`battery`, `altitude`, `heading`", "float", "0–100; 0–500 m; 0–360°."],
    ["", "`location`, `homeLocation`", "GeoJSON Point", "2dsphere index on `location`."],
    ["`telemetry`", "`kind`", "string", "position or thermal."],
    ["", "`droneId`, `incidentId`, `ts`", "string, string, float", "Indexed on incidentId + ts."],
    ["", "`gps`, `altitude`, `battery`, `heading`", "GeoJSON, float", "Position samples."],
    ["", "`frameBase64`, `aiResult`", "string, object", "Thermal samples: 64×64 PNG and classification, severity, confidence, hotspots, inferenceMs."],
    ["`firefighters`", "`_id`, `name`, `badge`", "string", "FF-nn."],
    ["", "`location`, `updatedAt`", "GeoJSON, float", "Latest known position."],
    ["`messages`", "`incidentId`, `channel`, `text`, `from`, `role`, `ts`", "mixed", "Channel: command, air or ground. Text 1–500 characters."],
    ["`reports`", "`_id`, `incidentId`, `generatedAt`, `generationMs`", "mixed", "One report per incident (replaced if regenerated)."],
    ["", "`summary`, `hotspotTimeline`, `worstFrame`", "object, array, object", "Timeline capped at about 200 points."],
    ["`counters`", "`_id`, `n`", "string, int", "Incident id sequence."],
  ], [14, 32, 16, 38], { size: 15 }),
  h3("Validation rules"),
  table(["Input", "Rule", "Enforced by", "Response"], [
    ["Login", "Username 3–40 and password 6–100 characters", "Pydantic", "422; wrong credentials 401"],
    ["CAD alert", "callId 3–40; priority 1–3; latitude −90..90; longitude −180..180; description at most 300", "Pydantic", "422"],
    ["Telemetry", "Altitude 0–500; battery 0–100; heading 0–360 (exclusive)", "Pydantic", "422"],
    ["Thermal frame", "Base64 PNG that decodes to exactly 64×64 greyscale", "Engine decoder", "422"],
    ["Message", "Text 1–500 characters; channel command, air or ground", "Pydantic", "422"],
    ["Identifiers", "Drone, incident and firefighter must exist", "Endpoint lookup", "404"],
  ], [16, 44, 18, 22]),
  h3("Privacy controls"),
  bullets([
    "**Role-based access:** the API checks the role in the signed token on every protected endpoint. Crew cannot raise CAD alerts or list firefighters (tested in IT-03); drone, telemetry and report endpoints are likewise restricted to commander, operator and admin in the code.",
    "**Event filtering:** crew WebSocket clients never receive telemetry, detection, hotspot, location or spread events (IT-07).",
    "**Credential handling:** passwords are stored only as salted hashes; tokens expire after 8 hours.",
    "**Encryption:** TLS 1.3 was verified when the server is started with a certificate (ST-02). Encryption at rest (AES-256) is a MongoDB Atlas setting and was not configured or verified in this prototype.",
    "**Personal information (POPIA):** firefighter locations and drone imagery are personal or potentially identifying data. A production deployment needs a documented purpose, retention limit and access log. Assignment 2 proposed 5-year retention for incident data; this is not implemented.",
  ]),
  h3("Backup approach"),
  p("**Prototype:** data lives in an in-memory store and is lost when the process stops. **Production plan:** MongoDB Atlas automated snapshots (daily, as stated in Assignment 2) and point-in-time restore on an Azure South Africa North cluster. This plan is documented but was not configured or tested."),

  h2("4.3 Main API interface"),
  p("Base path `/api/v1`. Every endpoint except login and health needs the header `Authorization: Bearer <token>`. Interactive OpenAPI documentation is generated by FastAPI at `/docs` (it loads its viewer assets from a CDN, so it needs internet access)."),
  table(["Method and path", "Roles", "Input", "Output / errors"], [
    ["POST `/auth/login`", "Any", "`username`, `password`", "`token`, `role`. 401 bad credentials."],
    ["POST `/cad/alerts`", "operator, admin", "CadAlert", "201 `incidentId`, `droneId`, `dispatchSeconds`, `dispatchStatus`. 409, 422."],
    ["GET `/incidents`, `/incidents/{id}`", "Any signed in", "none", "Incident list or document. 404."],
    ["POST `/incidents/{id}/close`", "commander, admin", "none", "`reportId`, `generationMs`. 409 if already closed."],
    ["GET `/incidents/{id}/report`", "commander, operator, admin", "none", "Report document. 404."],
    ["GET `/incidents/{id}/spread`", "commander, operator, admin", "optional `slope_deg` 0–45", "GeoJSON Feature (polygon, wind, reach)."],
    ["GET `/drones`, `/firefighters`", "commander, operator, admin", "none", "Lists."],
    ["POST `/drones/{id}/telemetry`", "operator, admin", "Telemetry", "202 accepted. 404, 422."],
    ["POST `/ai/analyse`", "operator, admin", "`droneId`, `incidentId`, `frameBase64`, `timestamp`", "`classification`, `severity`, `confidence`, `hotspots[]`, `inferenceMs`. 404, 422."],
    ["POST `/firefighters/{id}/location`", "crew, admin", "`lat`, `lon`", "202 accepted."],
    ["POST `/messages`, GET `/messages?incidentId=`", "Any signed in", "`incidentId`, `channel`, `text`", "201 delivered / message list."],
    ["POST `/sim/start`", "operator, admin", "`incidentId`, `timeScale`", "202 started (simulation only)."],
    ["GET `/health`", "None", "none", "`status: ok`."],
    ["WebSocket `/ws?token=`", "Any signed in", "token in query string", "Events: incident, telemetry, detection, hotspots, alert, location, message. Close code 4401 if the token is invalid."],
  ], [28, 17, 25, 30], { size: 15 }),
  h3("Error handling"),
  p("All errors use one JSON shape, `{\"error\": <message>, \"status\": <code>}`, except automatic field-level 422 responses from Pydantic. Codes used: 401 (no or invalid token), 403 (role not allowed), 404 (unknown id), 409 (duplicate or already closed), 422 (invalid input)."),
  h3("Real request and response examples"),
  p("Captured from the running application (`scripts/collect_evidence.py`).", { keepNext: true }),
  p("**POST /cad/alerts:** request", { keepNext: true }),
  code(js({ callId: "CAD-2026-0930-01", priority: 1, lat: -25.7479, lon: 28.2293, description: "Structure fire" })),
  p("Response (201)", { keepNext: true, before: 60 }),
  code(js(ex.cad_ok.body)),
  p("**POST /ai/analyse:** response (200), hotspots shortened", { keepNext: true, before: 80 }),
  code(js({ ...ex.analyse_ok.body, hotspots: ex.analyse_ok.body.hotspots.slice(0, 1) }).slice(0, 40)),
  p("**Error examples**", { keepNext: true, before: 80 }),
  table(["Case", "Status", "Body"], [
    ["No token", String(ex.no_token.status), "`" + JSON.stringify(ex.no_token.body) + "`"],
    ["Crew posts a CAD alert", String(ex.wrong_role.status), "`" + JSON.stringify(ex.wrong_role.body) + "`"],
    ["Duplicate call id", String(ex.cad_dup.status), "`" + JSON.stringify(ex.cad_dup.body) + "`"],
    ["Priority 7", String(ex.cad_invalid.status), "\"" + ex.cad_invalid.body.detail0 + "\" (Pydantic message)"],
    ["Invalid frame", String(ex.analyse_bad.status), "`" + JSON.stringify(ex.analyse_bad.body) + "`"],
  ], [24, 10, 66], { size: 15 }),

  h2("4.4 Installation, configuration and deployment"),
  h3("Minimum requirements"),
  table(["Item", "Prototype (measured)", "Production (from Assignment 2)"], [
    ["CPU / RAM", "2 vCPU, 4 GB RAM minimum (tested on 2 vCPU, 7 GB)", "8-core with GPU, 32 GB recommended"],
    ["Disk", "About 6 GB with the default PyTorch build (less with the CPU-only wheel used in the Dockerfile)", "1 TB SSD with cloud backup"],
    ["Software", "Python 3.11, pip, a modern browser; Docker optional", "Docker on Azure South Africa North, MongoDB Atlas"],
    ["Network", "None for the demo; internet for map tiles", "10 Mbps, 50 Mbps with 4G/5G failover recommended"],
  ], [16, 42, 42]),
  h3("Install and run (local demo)"),
  code([
    "cd firesight",
    "python3 -m venv .venv && . .venv/bin/activate",
    "pip install -r requirements.txt",
    "python -m app.ai.train                     # optional: retrain (weights are included)",
    "uvicorn app.main:app --port 8000           # open http://localhost:8000",
    "# demo accounts: operator1, commander1, crew1, admin1  (password: firesight123)",
  ]),
  h3("Configuration (environment variables)"),
  table(["Variable", "Purpose", "Default"], [
    ["`MONGO_URI`, `MONGO_DB`", "MongoDB Atlas connection; empty means in-memory demo store", "empty, `firesight`"],
    ["`JWT_SECRET`", "Signing key for tokens. **Set a long random value in production.**", "`dev-secret-change-me`"],
    ["`SIM_MODE`", "1 starts a simulated mission on every dispatch; 0 waits for real adapters", "1"],
    ["`SIM_TIME_SCALE`, `SIM_CRITICAL_AFTER_S`", "Demo speed-up of flight; seconds on scene before the simulated fire turns critical", "10, 25"],
    ["`OPENWEATHER_KEY`", "Live wind data; otherwise simulated wind is used", "empty"],
    ["`SIM_WIND_KMH`, `SIM_WIND_FROM`", "Simulated wind speed and direction (degrees it blows from)", "18, 270"],
  ], [30, 52, 18]),
  h3("Run the tests"),
  code([
    "PYTHONPATH=. pytest tests --cov=app --junitxml=artifacts/junit.xml",
    "python scripts/ui_capture.py        # dashboard screenshots and load-time measurement",
  ]),
  h3("Container deployment (files provided, not built or run)"),
  code([
    "export JWT_SECRET=<long random value> MONGO_URI=<atlas srv string>",
    "docker compose up --build            # API on port 8000",
    "# In Azure: push the image to a registry, run it on a container host behind an",
    "# Application Gateway that terminates TLS 1.3, and point MONGO_URI at Atlas.",
  ]),
  note("The Docker daemon was not available in the build environment, so the image build and container run are **untested**. That is why NFR-05 is Partial."),
];
